@page { margin: 0.1in; }
* { box-sizing: border-box; margin: 0; padding: 0; }
body { font-family: Arial, Helvetica, sans-serif; font-size: 8.5pt; color: #000; }
.challan-table { width: 100%; border-collapse: collapse; table-layout: fixed; }
.challan-table thead { display: table-header-group; }
.challan-table tfoot { display: table-footer-group; }
.challan-table tbody { display: table-row-group; }
.challan-table tbody td { border: 0.5px solid #000; padding: 3px 4px !important; vertical-align: top; font-size: 8pt; }
.col-header th { border: 0.5px solid #000; padding: 2px 2px !important; font-size: 7pt; font-weight: bold; text-align: center; background: #fff; line-height: 1.2; }
.total-row td { border: 0.5px solid #000; padding: 3px 4px !important; font-weight: bold; font-size: 8pt; }
.inner-tbl { border-collapse: collapse; width: 100%; }
.inner-tbl td { border: 0.5px solid #000; padding: 0 !important; font-size: 8.5pt; }
.p2-tbl { border-collapse: collapse; width: 100%; }
.p2-tbl td, .p2-tbl th { border: 0.5px solid #000; padding: 2px 3px !important; font-size: 7.5pt; }
.consignee-tbl tbody td { padding: 0px !important; }
